#[test]
fn every_persisted_affordance_surfaces_in_the_view() {
    let _w = World::in_process("corpus-affordances", cv_core::env::Env::enter_isolated);
    let mut missing = Vec::new();
    for h in HARNESSES {
        for v in subdirs(&corpus_root().join(h.name)) {
            let label = format!("{}/{}", h.name, v.file_name().unwrap().to_string_lossy());
            let adapter = (h.adapter)(&v);
            let mut refs = adapter.discover().expect("discover");
            if let Some(children) = h.children {
                let kids: Vec<SessionRef> = refs.iter().flat_map(children).collect();
                refs.extend(kids);
            }
            let mut seen = std::collections::BTreeSet::new();
            for r in &refs {
                let rows = cv_core::affordance::read(adapter.as_ref(), r).expect("affordances");
                for a in rows {
                    seen.insert(a.kind.as_str().to_string());
                    seen.insert(format!("{}/{}", a.kind.as_str(), a.action));
                }
            }
            for (prefix, wants) in PERSISTED {
                let applies = match prefix.strip_suffix('$') {
                    Some(exact) => label == exact,
                    None => label.starts_with(prefix),
                };
                if !applies {
                    continue;
                }
                for w in *wants {
                    if !seen.contains(*w) {
                        missing.push(format!("{label}: {w} (saw {seen:?})"));
                    }
                }
            }
        }
    }
    assert!(
        missing.is_empty(),
        "affordances the store persists but the view misses:\n{}",
        missing.join("\n")
    );
}

/// Query's independent oracle keeps the old full collector and old event/classification helpers.
/// Explicit corpus roots must also supply explicit-root side stores: SessionFacts's convenience
/// resolver otherwise uses the default harness home, which is a different store in this test.
#[test]
fn query_facts_match_collected_corpus() {
    use cv_core::query::{ExtFacts, Facts, SessionFacts, SessionQuery, TextSets, Tri};
    use std::collections::{HashMap, HashSet};

    struct ScopedFacts<'a> {
        full: SessionFacts<'a>,
        kinds: HashSet<cv_core::affordance::Kind>,
    }
    impl ExtFacts for ScopedFacts<'_> {
        fn tool(&self, n: &str) -> anyhow::Result<Tri> {
            self.full.tool(n)
        }
        fn touched(&self, n: &str) -> anyhow::Result<Tri> {
            self.full.touched(n)
        }
        fn text(&self, n: &str) -> anyhow::Result<Tri> {
            self.full.text(n)
        }
        fn has(&self, n: &str) -> anyhow::Result<Tri> {
            match cv_core::affordance::Kind::parse(n) {
                Some(kind) => Ok(Tri::of(self.kinds.contains(&kind))),
                None => self.full.has(n),
            }
        }
    }
    fn copy_tree(from: &Path, to: &Path) {
        fs::create_dir_all(to).unwrap();
        for entry in fs::read_dir(from).unwrap() {
            let entry = entry.unwrap();
            let target = to.join(entry.file_name());
            if entry.file_type().unwrap().is_dir() {
                copy_tree(&entry.path(), &target);
            } else {
                fs::copy(entry.path(), target).unwrap();
            }
        }
    }

    let world = World::in_process("query_corpus_oracle", cv_core::env::Env::enter_isolated);
    let mut checked = HashMap::<&str, usize>::new();
    for harness in HARNESSES {
        for version in subdirs(&corpus_root().join(harness.name)) {
            // SQLite adapters may create ancillary files; only operate on our scratch copy.
            let scratch = world
                .base
                .join("corpus")
                .join(harness.name)
                .join(version.file_name().unwrap());
            copy_tree(&version, &scratch);
            let adapter = (harness.adapter)(&scratch);
            for r in adapter.discover().unwrap() {
                let full =
                    cv_core::stream::collect_with(adapter.as_ref(), &r, &cv_core::Demand::LEAN.with_spans()).unwrap();
                let rows = cv_core::affordance::of_session(&full)
                    .unwrap()
                    .into_iter()
                    .chain(adapter.store_affordances(&r).unwrap());
                let mut counts = cv_core::affordance::Counts::new();
                for row in rows {
                    *counts.entry(row.kind).or_default() += 1;
                }
                let texts = TextSets::default();
                let scoped = ScopedFacts {
                    full: SessionFacts::new(&r, &full, &texts),
                    kinds: counts.keys().copied().collect(),
                };
                let mut queries = vec![
                    "tool:absent-query-tool".to_owned(),
                    "NOT tool:absent-query-tool".to_owned(),
                    "model:absent-query-model".to_owned(),
                    "NOT model:absent-query-model".to_owned(),
                    "touched:absent-query-path".to_owned(),
                    "has:errors".to_owned(),
                    "has:tools".to_owned(),
                    "has:images".to_owned(),
                    "NOT (has:errors AND model:absent-query-model)".to_owned(),
                    "has:tools OR has:images".to_owned(),
                    "NOT has:tools AND NOT has:images".to_owned(),
                ];
                queries.extend(
                    cv_core::affordance::Kind::ALL
                        .iter()
                        .map(|kind| format!("has:{}", kind.as_str())),
                );
                if let Some(model) = full
                    .model
                    .as_ref()
                    .or_else(|| full.messages.iter().find_map(|m| m.model.as_ref()))
                {
                    let quoted = serde_json::to_string(model).unwrap();
                    queries.extend([
                        format!("model={quoted}"),
                        format!("model:{quoted} AND NOT model:absent-query-model"),
                    ]);
                }
                let resolver = full.resolver();
                let events: Vec<_> = full
                    .messages
                    .iter()
                    .enumerate()
                    .map(|(i, m)| cv_core::events::extract(m, i, full.cwd.as_deref(), &resolver))
                    .collect::<anyhow::Result<Vec<_>>>()
                    .unwrap()
                    .into_iter()
                    .flatten()
                    .collect();
                if let Some(tool) = events.iter().find_map(|e| e.tool.as_ref()) {
                    queries.push(format!(
                        "tool:{} AND NOT tool:absent-query-tool",
                        serde_json::to_string(tool).unwrap()
                    ));
                }
                if let Some(target) = events
                    .iter()
                    .filter(|e| matches!(e.kind, "file_edit" | "file_read"))
                    .find_map(|e| e.target.as_ref())
                {
                    queries.push(format!("touched:{}", serde_json::to_string(target).unwrap()));
                }
                for source in queries {
                    let query = SessionQuery::parse(&source).unwrap();
                    let expected = query
                        .matches(&Facts {
                            r: &r,
                            session: Some(&full),
                            ext: &scoped,
                        })
                        .unwrap();
                    let actual = cv_core::query::matches_streamed(&query, adapter.as_ref(), &r, &texts).unwrap();
                    assert_eq!(
                        actual,
                        expected,
                        "{} {} {}: {source}",
                        harness.name,
                        version.display(),
                        r.id
                    );
                }
                // Presence queries cannot reveal count inflation: compare the entire tiny counter
                // against the old row collector, including this adapter's own side stores.
                let mut discard = cv_core::stream::Discard;
                let counted = cv_core::stream::stream_counted(
                    adapter.as_ref(),
                    &r,
                    &cv_core::Demand::LEAN.with_spans(),
                    &mut discard,
                    Default::default(),
                )
                .unwrap()
                .counted;
                assert_eq!(
                    counted.unwrap().counts,
                    counts,
                    "counts: {} {} {}",
                    harness.name,
                    version.display(),
                    r.id
                );
                *checked.entry(harness.name).or_default() += 1;
            }
        }
    }
    assert!(checked.len() >= 10, "cross-harness coverage: {checked:?}");
    eprintln!("query oracle checked native sessions: {checked:?}");
}

/// The count contract ([`SessionRef::message_count`]): the number a listing shows is the number
/// of turns ([`cv_core::ir::Message::is_turn`]) a full read of the same session yields. For an
/// adapter whose discovery counts, that is the discovered count; for one that defers, it is the
/// count the catalog holds after an index pass records it, as `cv index` then `cv ls` see it.
#[test]
fn every_listed_count_is_the_full_read_turn_count() {
    fn copy_tree(from: &Path, to: &Path) {
        fs::create_dir_all(to).unwrap();
        for entry in fs::read_dir(from).unwrap() {
            let entry = entry.unwrap();
            let target = to.join(entry.file_name());
            if entry.file_type().unwrap().is_dir() {
                copy_tree(&entry.path(), &target);
            } else {
                fs::copy(entry.path(), target).unwrap();
            }
        }
    }
    let world = World::in_process("count_contract", cv_core::env::Env::enter_isolated);
    let mut wrong = Vec::new();
    let mut checked = BTreeMap::<&str, (usize, usize)>::new();
    for harness in HARNESSES {
        for version in subdirs(&corpus_root().join(harness.name)) {
            let scratch = world
                .base
                .join("count-corpus")
                .join(harness.name)
                .join(version.file_name().unwrap());
            copy_tree(&version, &scratch);
            let adapter = (harness.adapter)(&scratch);
            let mut refs = adapter.discover().unwrap();
            if let Some(children) = harness.children {
                let kids: Vec<SessionRef> = refs.iter().flat_map(children).collect();
                refs.extend(kids);
            }
            for r in refs {
                let turns = |demand: &cv_core::Demand| {
                    cv_core::stream::collect_with(adapter.as_ref(), &r, demand)
                        .unwrap()
                        .messages
                        .iter()
                        .filter(|m| m.is_turn())
                        .count()
                };
                let reference = turns(&cv_core::Demand::LEAN.with_spans());
                // A complete read also carries rows outside the conversation (rewound, superseded,
                // carried) for round-trip, and never certifies a count: every other tier agrees.
                for demand in [cv_core::Demand::USAGE, cv_core::Demand::FACTS, cv_core::Demand::RICH] {
                    let n = turns(&demand);
                    if n != reference {
                        wrong.push(format!(
                            "{} {} {}: {demand:?} reads {n} turns, lean {reference}",
                            harness.name,
                            version.file_name().unwrap().to_string_lossy(),
                            r.id
                        ));
                    }
                }
                let entry = checked.entry(harness.name).or_default();
                let listed = match r.message_count {
                    Some(n) => {
                        entry.0 += 1;
                        n
                    }
                    None => {
                        // Deferred: what `cv index` records, then what the catalog lists.
                        entry.1 += 1;
                        cv_core::catalog::sync(std::slice::from_ref(&r));
                        // A complete read first (an export, a port) must not decide the count.
                        cv_core::stream::collect_with(adapter.as_ref(), &r, &cv_core::Demand::COMPLETE).unwrap();
                        cv_core::stream::stream_counted(
                            adapter.as_ref(),
                            &r,
                            &cv_core::Demand::LEAN.with_spans(),
                            &mut cv_core::stream::Discard,
                            cv_core::stream::Pass::RECORD,
                        )
                        .unwrap();
                        cv_core::catalog::lookup(&r.id, Some(r.harness))
                            .into_iter()
                            .find(|l| l.path == r.path)
                            .and_then(|l| l.message_count)
                            .unwrap_or_else(|| panic!("{} {}: indexed but still uncounted", harness.name, r.id))
                    }
                };
                if listed != reference {
                    wrong.push(format!(
                        "{} {} {}: listed {listed}, full read {reference} turns",
                        harness.name,
                        version.file_name().unwrap().to_string_lossy(),
                        r.id
                    ));
                }
            }
        }
    }
    eprintln!("count contract checked (discovered, deferred) per harness: {checked:?}");
    assert!(
        wrong.is_empty(),
        "listed counts break the contract:\n{}",
        wrong.join("\n")
    );
}
